command:
apk add --no-cache git bash curl corepack >/dev/null 2>&1 || true; corepack enable >/dev/null 2>&1 || true; cd /app; if [ -n "$GIT_REPOSITORY_URL" ]; then AUTH_REPO_URL="$GIT_REPOSITORY_URL"; if [ -n "$GITHUB_TOKEN" ]; then AUTH_REPO_URL=$(echo "$GIT_REPOSITORY_URL" | sed -E "s#https://#https://${GITHUB_TOKEN}@#"); fi; if [ ! -d .git ]; then echo '[Runner] Clonando repositório...'; git clone --branch "$GIT_BRANCH" "$AUTH_REPO_URL" . ; else echo '[Runner] Atualizando repositório...'; git remote set-url origin "$AUTH_REPO_URL"; git fetch origin "$GIT_BRANCH"; git checkout "$GIT_BRANCH"; git pull origin "$GIT_BRANCH"; fi; else if [ ! -f package.json ] && [ ! -f server.js ] && [ ! -f index.js ]; then echo '[Runner] Criando aplicação de exemplo...'; cat << 'EOF' > server.js
const http = require('http');
const port = process.env.PORT || 3000;
http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ status: 'online', runtime: 'Node.js 24', message: 'ServApp Node.js ativo no Cosmos-Server' }));
}).listen(port, () => console.log(`Servidor ouvindo na porta ${port}`));
EOF
fi; fi; if [ -n "$INSTALL_CMD" ] && [ -f package.json ]; then echo "[Runner] Executando: $INSTALL_CMD"; eval "$INSTALL_CMD"; fi; if [ -n "$BUILD_CMD" ]; then echo "[Runner] Executando: $BUILD_CMD"; eval "$BUILD_CMD"; fi; echo "[Runner] Iniciando serviço: $START_CMD"; if [ -f server.js ] && [ ! -f package.json ] && [ "$START_CMD" = "npm start" ]; then exec node server.js; else exec /bin/sh -c "$START_CMD"; fi
